 1. The driver unconditionally issues a ring abort even when the ring has
    already stopped.
 2. The completion used to wait for abort completion is never
    re-initialized, resulting in incorrect wait behavior.
 3. The abort sequence unintentionally clears RING_CTRL_ENABLE, which
    resets hardware ring pointers and disrupts the controller state.
 4. If the ring is already stopped, the abort operation should be
    considered successful without attempting further action.

Fix the abort handling by checking whether the ring is running before
issuing an abort, re-initializing the completion when needed, ensuring that
RING_CTRL_ENABLE remains asserted during abort, and treating an already
stopped ring as a successful condition.

Fixes: 9ad9a52cce282 ("i3c/master: introduce the mipi-i3c-hci driver")
Cc: stable@vger.kernel.org
Signed-off-by: Adrian Hunter <adrian.hunter@intel.com>
Reviewed-by: Frank Li <Frank.Li@nxp.com>
Link: https://patch.msgid.link/20260306072451.11131-9-adrian.hunter@intel.com
Signed-off-by: Alexandre Belloni <alexandre.belloni@bootlin.com>

Here is the root cause:
it unconditionally issued a ring abort without checking if the ring was running, it did not reinitialize the completion before waiting, it wrote only RING_CTRL_ABORT which cleared RING_CTRL_ENABLE causing hardware pointer reset, and it did not treat an already stopped ring as success, leading to potential wait on already completed abort or spurious warnings.

Here is the patch:

 static bool hci_dma_dequeue_xfer(struct i3c_hci *hci,
 				 struct hci_xfer *xfer_list, int n)
 {
 	struct hci_rings_data *rings = hci->io_data;
 	struct hci_rh_data *rh = &rings->headers[xfer_list[0].ring_number];
 	unsigned int i;
 	bool did_unqueue = false;
+	u32 ring_status;

 	guard(mutex)(&hci->control_mutex);

-	/* stop the ring */
-	rh_reg_write(RING_CONTROL, RING_CTRL_ABORT);
-	if (wait_for_completion_timeout(&rh->op_done, HZ) == 0) {
-		/*
-		 * We're deep in it if ever this condition is ever met.
-		 * Hardware might still be writing to memory, etc.
-		 */
-		dev_crit(&hci->master.dev, "unable to abort the ring\n");
-		WARN_ON(1);
+	ring_status = rh_reg_read(RING_STATUS);
+	if (ring_status & RING_STATUS_RUNNING) {
+		/* stop the ring */
+		reinit_completion(&rh->op_done);
+		rh_reg_write(RING_CONTROL, RING_CTRL_ENABLE | RING_CTRL_ABORT);
+		wait_for_completion_timeout(&rh->op_done, HZ);
+		ring_status = rh_reg_read(RING_STATUS);
+		if (ring_status & RING_STATUS_RUNNING) {
+			/*
+			 * We're deep in it if ever this condition is ever met.
+			 * Hardware might still be writing to memory, etc.
+			 */
+			dev_crit(&hci->master.dev, "unable to abort the ring\n");
+			WARN_ON(1);
+		}
 	}

 	spin_lock_irq(&hci->lock);

 	for (i = 0; i < n; i++) {
 		struct hci_xfer *xfer = xfer_list + i;
 		int idx = xfer->ring_entry;

 		/*
 		 * At the time the abort happened, the xfer might have
 		 * completed already. If not then replace corresponding
 		 * descriptor entries with a no-op.
 		 */
 		if (idx >= 0) {
 			u32 *ring_data = rh->xfer + rh->xfer_struct_sz * idx;

 			/* store no-op cmd descriptor */
 			*ring_data++ = FIELD_PREP(CMD_0_ATTR, 0x7);
 			*ring_data++ = 0;
 			if (hci->cmd == &mipi_i3c_hci_cmd_v2) {
 				*ring_data++ = 0;
 				*ring_data++ = 0;
 			}

 			/* disassociate this xfer struct */
 			rh->src_xfers[idx] = NULL;

 			/* and unmap it */
 			hci_dma_unmap_xfer(hci, xfer, 1);

 			did_unqueue = true;
 		}
 	}

 	/* restart the ring */
 	rh_reg_write(RING_CONTROL, RING_CTRL_ENABLE);

 	spin_unlock_irq(&hci->lock);

 	return did_unqueue;
 }



